using namespace std;
// Number of survivors: dead[i] = has a higher friend and every lower friend is dead.
int countSurvivors(int n, const vector<set<int>>& adj) {
    vector<char> dead(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        bool hasHigher = false, allLowerDead = true;
        for (int j : adj[i]) {
            if (j > i) hasHigher = true;
            else if (!dead[j]) allLowerDead = false;
        }
        dead[i] = hasHigher && allLowerDead;
    }
    int alive = 0;
    for (int i = 1; i <= n; i++) alive += !dead[i];
    return alive;
}
int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    vector<set<int>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].insert(v);
        adj[v].insert(u);
    }
    int q;
    scanf("%d", &q);
    while (q--) {
        int t;
        scanf("%d", &t);
        if (t == 1) {
            int u, v;
            scanf("%d %d", &u, &v);
            adj[u].insert(v);
            adj[v].insert(u);
        } else if (t == 2) {
            int u, v;
            scanf("%d %d", &u, &v);
            adj[u].erase(v);
            adj[v].erase(u);
        } else {
            printf("%d\n", countSurvivors(n, adj));
        }
    }
}

