// True if the GCD-sequence of v is non-decreasing.
bool good(const vector<int>& v) {
    int prev = 0;
    for (size_t i = 0; i + 1 < v.size(); i++) {
        int g = __gcd(v[i], v[i + 1]);
        if (g < prev) return false;
        prev = g;
    }
    return true;
}
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        vector<int> a(n);
        for (auto& x : a) scanf("%d", &x);
        int p = -1;
        for (int i = 0; i + 2 < n && p < 0; i++)
            if (__gcd(a[i], a[i + 1]) > __gcd(a[i + 1], a[i + 2])) p = i;
        bool ans = (p < 0);
        for (int k = p; k >= 0 && k <= p + 2 && k < n && !ans; k++) {
            vector<int> b;
            for (int i = 0; i < n; i++)
                if (i != k) b.push_back(a[i]);
            ans = good(b);
        }
        puts(ans ? "YES" : "NO");
    }
}

