// Apply +1 or -1 to the count of length x and keep pairs_ and quad correct.
void upd(int x, int d) {
    pairs_ -= cnt[x] / 2;
    quad -= (cnt[x] >= 4);
    cnt[x] += d;
    pairs_ += cnt[x] / 2;
    quad += (cnt[x] >= 4);
}
