#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Minimum |(a^x) - (b^x)| over 0 <= x <= r.
ll solve(ll a, ll b, ll r) {
    int T = -1;
    for (int i = 60; i >= 0; i--)
        if (((a >> i) & 1) != ((b >> i) & 1)) { T = i; break; }
    if (T < 0) return 0;
    ll best = LLONG_MAX;
    for (int sg : {1, -1}) {
        bool tight = true, ok = true;
        ll D = 0;
        for (int i = T; i >= 0; i--) {
            int ai = (a >> i) & 1, bi = (b >> i) & 1, ri = (r >> i) & 1;
            int xi = 0;
            if (ai != bi) {
                int want = (i == T) ? sg : -sg;
                xi = ai ^ (want == 1);
                if (tight && xi > ri) {
                    if (i == T) { ok = false; break; }
                    xi = 1 - xi;
                }
                int actual = ((ai ^ xi) == 1) ? 1 : -1;
                D += (ll)actual * (1LL << i);
            }
            if (tight && xi < ri) tight = false;
        }
        if (ok) best = min(best, llabs(D));
    }
    return best;
}
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        ll a, b, r;
        scanf("%lld %lld %lld", &a, &b, &r);
        printf("%lld\n", solve(a, b, r));
    }
}

