    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        vector<int> a(n);
        for (auto& x : a) scanf("%d", &x);
        // sm[i] = mex of a[i..n-1]
        vector<int> sm(n + 1, 0), present(n + 2, 0);
        int mex = 0;
        for (int i = n - 1; i >= 0; i--) {
            present[a[i]] = 1;
            while (present[mex]) mex++;
            sm[i] = mex;
        }
        vector<int> b, stamp(n + 2, -1);
        int i = 0, step = 0;
        while (i < n) {
            int M = sm[i];
            if (M == 0) {
                b.push_back(0);
                i++;
                continue;
            }
            int seen = 0, j = i;
            for (;; j++) {
                int v = a[j];
                if (v < M && stamp[v] != step) {
                    stamp[v] = step;
                    seen++;
                }
                if (seen == M) break;
            }
            b.push_back(M);
            i = j + 1;
            step++;
        }
        printf("%d\n", (int)b.size());
        for (size_t k = 0; k < b.size(); k++) printf("%d ", b[k]);
        puts("");
    }
}

