int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, m, k;
        scanf("%d %d %d", &n, &m, &k);
        int w;
        scanf("%d", &w);
        vector<ll> a(w);
        for (auto& x : a) scanf("%lld", &x);
        // number of k-windows (starts in [0, len-k]) that cover index i
        auto cover = [&](int i, int len) {
            int lo = max(0, i - k + 1), hi = min(i, len - k);
            return hi - lo + 1;
        };
        vector<ll> cov;
        cov.reserve((size_t)n * m);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                cov.push_back((ll)cover(i, n) * cover(j, m));
        sort(cov.rbegin(), cov.rend());
        sort(a.rbegin(), a.rend());
        ll ans = 0;
        for (int p = 0; p < w; p++) ans += a[p] * cov[p];
        printf("%lld\n", ans);
    }
}

