            int a, b;
            if (d[i] == -1) { a = lo[i - 1]; b = hi[i - 1] + 1; }
            else { a = lo[i - 1] + d[i]; b = hi[i - 1] + d[i]; }
            lo[i] = max(a, l[i]);
            hi[i] = min(b, r[i]);
