#include <bits/stdc++.h>
using namespace std;
vector<int> par;
int findp(int x) {
    while (par[x] != x) {
        par[x] = par[par[x]];
        x = par[x];
    }
    return x;
}
void unite(int a, int b) {
    a = findp(a);
    b = findp(b);
    if (a != b) par[a] = b;
}
int main() {
    int T;
    scanf("%d", &T);
    static char s[200005], t[200005];
    while (T--) {
        int n, k;
        scanf("%d %d", &n, &k);
        scanf("%s %s", s, t);
        par.assign(n, 0);
        for (int i = 0; i < n; i++) par[i] = i;
        for (int i = 0; i + k < n; i++) unite(i, i + k);
        for (int i = 0; i + k + 1 < n; i++) unite(i, i + k + 1);
        vector<int> bucket((size_t)n * 26, 0);
        for (int i = 0; i < n; i++) {
            int r = findp(i);
            bucket[(size_t)r * 26 + (s[i] - 'a')]++;
            bucket[(size_t)r * 26 + (t[i] - 'a')]--;
        }
        bool ok = true;
        for (int x : bucket)
            if (x != 0) { ok = false; break; }
        puts(ok ? "YES" : "NO");
    }
}

