#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    vector<long long> a(n);
    for (auto& x : a) scanf("%lld", &x);
    vector<long long> d;
    d.reserve(n);
    for (int i = 1; i < n; i++) d.push_back(a[i] - a[i - 1]);
    sort(d.rbegin(), d.rend());
    long long cost = a[n - 1] - a[0];
    for (int i = 0; i < k - 1; i++) cost -= d[i];
    printf("%lld\n", cost);
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, x;
        scanf("%d %d", &n, &x);
        if (x != n && n % x != 0) {
            puts("-1");
            continue;
        }
        vector<int> p(n + 1);
        for (int i = 1; i <= n; i++) p[i] = i;
        p[1] = x;
        p[n] = 1;
        if (x != n) {
            int cur = x;
            while (cur != n) {
                int nxt = -1;
                for (int d = cur + 1; d <= n; d++)
                    if (n % d == 0 && d % cur == 0) { nxt = d; break; }
                p[cur] = nxt;
                cur = nxt;
            }
        }
        for (int i = 1; i <= n; i++) printf("%d%c", p[i], i == n ? '\n' : ' ');
    }
}
